def main():
    with open(INP, encoding="utf-8") as f:
        src = json.load(f)
    if len(src) != len(ZH):
        raise SystemExit("段数不符: 输入 %d, 译文 %d" % (len(src), len(ZH)))
    out = [{"k": s["k"], "zh": z} for s, z in zip(src, ZH)]
    # 自检
    assert len(out) == len(src)
    for a, b in zip(src, out):
        assert a["k"] == b["k"]
        assert b["zh"].strip()
        for bad in ("[", "]", ">", "http"):
            assert bad not in b["zh"], (a["k"], bad)
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
        f.write("\n")
    print("wrote", OUT, len(out), "segments")


if __name__ == "__main__":
    main()
